   var battery=go.AddComponent<CollectibleItem>();battery.kind=CollectibleKind.Battery;var h=go.AddComponent<WhistleHighlightable>();h.interactions=new MonoBehaviour[]{battery};h.targets=new[]{go.GetComponent<Renderer>()};h.outlineMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/HorrorGameplay/Data/Whistle/Discovery/Outline.mat");go.SetActive(true);yield return null;
   var context=new WhistleContext(s,f.camera.transform.position,Vector3.forward,WhistleKind.Tap,0,1,"SchoolCEEP","test");
   foreach(WhistleCategory category in Enum.GetValues(typeof(WhistleCategory))){h.category=category;Assert.That(h.Reveal(context,true),Is.True,category.ToString());Assert.That(h.ThroughWall,Is.True);h.Clear();}
   battery.enabled=false;Assert.That(h.Reveal(context,true),Is.False);battery.enabled=true;Assert.That(h.Reveal(context,true),Is.True);h.Tick(config.effectDuration+config.pulseExpansionSeconds+1);Assert.That(h.Visible,Is.False,"Temporary x-ray expires.");
   Assert.That(h.Reveal(context,true),Is.True);battery.RestoreState("{\"collected\":true}");Assert.That(h.Visible,Is.False);go.SetActive(true);Assert.That(h.Reveal(context,true),Is.False,"Even a saved collected item reactivated by another system must not glow.");
   battery.RestoreState("{\"collected\":false}");go.transform.position=f.camera.transform.position+Vector3.forward*25;Assert.That(h.Reveal(context,true),Is.False);yield return null;
  }
  [UnityTest,Category("WhistleXray")]public IEnumerator DoorsNeverReceiveWhistleHighlights(){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.SetActive(false);go.transform.SetParent(f.root.transform);go.AddComponent<InteractiveDoor>();var h=go.AddComponent<WhistleHighlightable>();h.targets=new[]{go.GetComponent<Renderer>()};go.SetActive(true);yield return null;Assert.That(h.enabled,Is.False);Assert.That(h.Reveal(new WhistleContext(s,go.transform.position,Vector3.forward,WhistleKind.Tap,0,1,"SchoolCEEP","test"),true),Is.False);Assert.That(go.GetComponentsInChildren<Renderer>(true).Length,Is.EqualTo(1),"No door outline shell should be allocated.");}
