   for(int i=0;i<40;i++){var go=f.Child("Nearby interactive "+i);go.layer=30;go.transform.position=f.camera.transform.position+new Vector3((i%8)-4,0,3+i/8);go.AddComponent<SphereCollider>().isTrigger=true;var item=go.AddComponent<CollectibleItem>();item.kind=CollectibleKind.Battery;var h=go.AddComponent<WhistleHighlightable>();h.interactions=new MonoBehaviour[]{item};}
   Physics.SyncTransforms();sense.Pulse(new WhistleContext(s,f.camera.transform.position,Vector3.forward,WhistleKind.Tap,0,1,"SchoolCEEP","test"));Assert.That(sense.LastOverlapCount,Is.EqualTo(40));Assert.That(sense.ActiveCount,Is.EqualTo(40));Assert.That(sense.BufferSaturated,Is.False);sense.Clear();Assert.That(sense.ActiveCount,Is.Zero);yield return null;
  }
