 public sealed partial class BeforeDemolitionSchoolSceneTests{
  [UnityTest,Category("WhistleXray"),Timeout(90000)]public IEnumerator NativeSchoolCoversEveryWorldInteractionIncludingBatteries(){
   var all=game.gameObject.scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MonoBehaviour>(true)).Where(m=>m is IInteractable&&!(m is InteractiveDoor)&&!(m is SchoolAreaRestriction)&&!m.GetComponent<LockableDoor>()).ToArray();var highlights=game.gameObject.scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<WhistleHighlightable>(true)).ToArray();var evidence=flow.GetComponent<SecretaryEvidence>();var maskedClues=evidence.footprintLookPoint.GetComponents<MonoBehaviour>().Where(m=>m is IInteractable).ToArray();foreach(var item in all)Assert.That(highlights.Any(h=>h.interactions.Contains(item))||maskedClues.Contains(item)&&evidence.footprints.Length==4,Is.True,item.GetType().Name+" / "+item.name);Assert.That(highlights.SelectMany(h=>h.interactions).Concat(maskedClues).Distinct().Count(),Is.EqualTo(all.Length),"The textured footprint clue owns its masked visual response; mesh outlines would fill entire decal quads.");Assert.That(highlights.Any(h=>h.GetComponent<InteractiveDoor>()||h.GetComponent<SchoolAreaRestriction>()),Is.False,"Doors are excluded from the whistle.");var rendererOwners=highlights.SelectMany(h=>h.targets).ToArray();Assert.That(rendererOwners.Distinct().Count(),Is.EqualTo(rendererOwners.Length),"Each physical mesh has a single highlight owner.");
   // Phone auto-open is covered separately; its modal deliberately suppresses whistle rendering.
   var phone=game.GetComponent<PhoneMessages>();if(phone){phone.Close();phone.enabled=false;}game.tutorials?.SetMode(TutorialMode.Off);
   var tool=WhistleSystem.For(game);tool.LearnLore();Assert.That(tool.BlowTap(),Is.True);Assert.That(UnityEngine.Object.FindObjectsByType<AudioSource>(FindObjectsInactive.Exclude).Any(a=>a.clip==tool.config.tapClip&&a.isPlaying),Is.True,"Recorded human whistle actually starts on an audio source.");yield return null;var sense=game.GetComponent<WhistleSense>();Assert.That(sense.BufferSaturated,Is.False);Assert.That(sense.ActiveCount,Is.GreaterThan(0));
   var battery=all.OfType<CollectibleItem>().First(b=>b.kind==CollectibleKind.Battery&&b.gameObject.activeInHierarchy);game.player.Warp(battery.transform.position+Vector3.forward*3,180);yield return null;tool.State.cooldownRemaining=0;Assert.That(tool.BlowTap(),Is.True,"Second accepted tap");var hBattery=highlights.Single(h=>h.interactions.Contains(battery));yield return Until(()=>hBattery.Visible,"The expanding pulse reaches the battery",3);Assert.That(hBattery.Reveal(new WhistleContext(tool,game.player.transform.position,Vector3.back,WhistleKind.Tap,0,1,"SchoolCEEP","test"),true),Is.True,"Battery remains an eligible interaction");Assert.That(hBattery.ThroughWall,Is.True);
   var mirror=all.OfType<BeforeDemolitionMirrorFlow>().Single();var hMirror=highlights.Single(h=>h.interactions.Contains(mirror));Assert.That(hMirror.targets.All(r=>r.transform.IsChildOf(mirror.glassVisual.transform)),Is.True,"Only mirror glass, never child/Helena apparition meshes.");
   var config=tool.config;Assert.That(config.tapClip,Is.Not.Null,"Use the currently bound recording; approved SFX replacements can change its filename");Assert.That(config.holdClip,Is.Not.Null);Assert.That(config.tapClip.loadState,Is.EqualTo(AudioDataLoadState.Loaded));Assert.That(config.holdClip.loadState,Is.EqualTo(AudioDataLoadState.Loaded));var samples=new float[config.tapClip.samples];Assert.That(config.tapClip.GetData(samples,0),Is.True);Assert.That(samples.Any(x=>Mathf.Abs(x)>.05f),Is.True);
   var dir="C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/WhistleXray20261031";Directory.CreateDirectory(dir);File.WriteAllText(dir+"/native-coverage.json",JsonUtility.ToJson(new XrayCoverage{interactions=all.Length,highlights=highlights.Length,batteries=all.OfType<CollectibleItem>().Count(b=>b.kind==CollectibleKind.Battery),activeHighlights=sense.ActiveCount,saturated=sense.BufferSaturated},true));
  }
  [Serializable]class XrayCoverage{public int interactions,highlights,batteries,activeHighlights;public bool saturated;}
